/**
 * Belirtilen sınıf (1-6) için 55 haftalık Sahabe Kıssaları müfredat girişlerini üretir.
 * - 1, 2, 3. sınıflar: Ortaokul müfredatı
 * - 4, 5, 6. sınıflar: Lise müfredatı
 * - Hafta 1-16: Eylül - Aralık 2026 (4 ay x 4 hafta)
 * - Hafta 17-48: Ocak - Ağustos 2027 (8 ay x 4 hafta)
 * - Hafta 49-55: Ekstra 1-7 (48 haftalık standart müfredat kuralı sonrası ilave kartlar)
 */
export function getSahabeEntriesForGrade(grade: number): CurriculumEntry[] {
  const items = grade <= 3 ? ortaokulSahabeCurriculum : liseSahabeCurriculum;

  return items.map((item) => {
    if (item.weekNumber <= 48) {
      const monthIndex = Math.floor((item.weekNumber - 1) / 4); // 0..11
      const month = monthIndex < 4 ? 9 + monthIndex : monthIndex - 3;
      const year = monthIndex < 4 ? 2026 : 2027;
      const weekInMonth = ((item.weekNumber - 1) % 4) + 1;
      const id = makeSahabeEntryId(month, weekInMonth, grade, false);

      return {
        id,
        grade,
        categoryId: "sahabe-kissalari",
        month,
        week: weekInMonth,
        year,
        isExtra: false,
        title: item.title,
        body: item.body,
      };
    }

    const extraOrder = item.weekNumber - 48; // 1..7
    const id = makeSahabeEntryId(8, 4, grade, true, extraOrder);

    return {
      id,
      grade,
      categoryId: "sahabe-kissalari",
      month: 8,
      week: 4,
      year: 2027,
      isExtra: true,
      extraOrder,
      title: item.title,
      body: item.body,
    };
  });
}

/**
 * 6 Belçika sınıfı için tüm Sahabe kayıtlarını döner (toplam 330 kayıt).
 */
export function getAllSahabeEntries(): CurriculumEntry[] {
  const all: CurriculumEntry[] = [];
  for (let grade = 1; grade <= 6; grade++) {
    all.push(...getSahabeEntriesForGrade(grade));
  }
  return all;
}
